        content: "포뮬레시아정을 안전하게 보관하려면 실온(15~30도)에 두세요. 직사광선과 습기를 피해 서늘한 곳에 보관하고, 욕실이나 주방 싱크대처럼 습한 환경은 피해요.\n\n어린이 손에 닿지 않는 곳에 두고, 임신 가능성이 있는 여성도 접촉하지 않도록 주의해요. 정제가 부서진 경우 임산부가 만지지 않도록 각별히 보관해요.\n\n유통기한이 지난 포뮬레시아정은 약국의 폐의약품 수거함에 버려요. 일반 쓰레기나 하수구에 버리지 마세요. 장기 복용 약이라 여분을 보관할 경우, 원래 포장 상태로 서늘하고 건조한 곳에 두면 유통기한까지 안전해요.",
