        "content": "식약처 허가사항이 정한 금기 대상은 분명해요. 모나정은 소아환자나 여성에게 투여해서는 안 돼요. 임부 또는 임신 가능성이 있는 여성은 복용은 물론 부서진 정제를 만져서도 안 되죠. 5α-환원효소 억제제는 테스토스테론이 디하이드로테스토스테론으로 전환되는 걸 저해해서, 임부가 복용하면 남성태아 외부생식기의 비정상을 초래할 수 있거든요.\n\n체질 관련 금기도 있어요. 허가사항은 유당을 함유하고 있어 갈락토오스 불내성, Lapp 유당분해효소 결핍증, 포도당-갈락토오스 흡수장애 같은 유전적 문제가 있는 환자에게 투여하면 안 된다고 적어요. 이 약 또는 구성성분에 과민반응이 있는 환자, 전립샘비대증 등으로 다른 5α-환원효소 억제제를 복용 중인 환자도 금기죠.\n\n신중 투여 대상도 알아두세요. 피나스테리드는 간에서 광범위하게 대사되므로 간기능에 이상이 있는 환자는 주의해야 해요. 약물상호작용은 임상적으로 중요한 게 밝혀진 바 없지만, 복용 약이 있다면 처방 단계에서 의사와 함께 확인하면 안전해요."
