        "answer": "정량을 지키고 통째로 삼키세요. 그게 출발점이에요. 식약처 허가사항은 1일 1회 1정(0.5mg)을 씹거나 쪼개지 말고 식사와 무관하게 먹으라고 안내해요. 쪼개면 코팅이 깨져요. 임신 가능성이 있는 여성이 피부로 흡수할 틈이 생기거든요. 고령이라 전립선암 검진을 받는 분은 PSA가 투여 6개월 뒤 약 50%까지 내려가요. 검사 전에 복용 사실을 의사에게 알려야 결과가 제대로 읽혀요."
