        "content": "두타케어정0.5밀리그램(두타스테리드)은 식약처 허가사항상 양성 전립선 비대증 증상을 누그러뜨리는 데 써요. 성인 남성(만 18~50세)의 남성형 탈모를 다스리는 효능도 함께 허가됐어요. 전립선 쪽으로는 갑자기 소변이 막히는 급성 요저류 위험과 수술까지 가는 경우도 줄여 줘요.\n\n반감기가 약 3~5주로 긴 축이라 혈중 농도가 고르게 유지돼요. 다만 효과가 더디게 자리 잡는 만큼 부작용도 더디게 빠져요. 늦게 들어오고 늦게 나간다고 새기면 편하네요. 탈모용이라면 50세를 넘긴 남성형 탈모 환자의 유효성 자료는 없다고 허가사항이 선을 그었어요. 효과가 났는지 따지거나 약을 바꾸는 일은 진료를 거쳐 결정하세요."
