          "1일 1회 1캡슐이에요. 빈속이든 식후든 무방해요. 식약처 허가사항 기준 복용법이고, 생활 루틴에 맞춰 정해진 시간에 챙기면 돼요.\n\n연질캡슐이라 한 가지 꼭 지켜야 할 점이 있어요. 캡슐 내용물에 구강이나 인두 점막이 노출되면 자극이 생기므로, 두타리드연질캡슐은 씹거나 쪼개지 않고 물과 함께 통째로 삼켜야 해요. 목에 걸릴 것 같으면 충분한 물로 한 번에 넘기는 게 맞아요. 신장 기능에 이상이 있거나 노인 환자라도 용량 조절 없이 동일하게 1일 1회 1캡슐을 복용해요.\n\n여성과 임부는 두타리드연질캡슐 캡슐 자체를 만지는 것도 주의가 필요해요. 허가사항 경고에 따르면 이 약은 피부로 흡수되며, 임신 가능성이 있는 여성이 캡슐에 접촉했을 경우 즉시 물과 비누로 씻어내야 해요.",
