        "content": "가장 신경 쓰이는 건 성기능 쪽이에요. 식약처 허가사항을 보면, 피나스테리드 1mg을 남성 탈모 환자에게 1년간 쓴 임상에서 성욕감퇴가 1.8%, 발기부전이 1.3%, 사정장애가 1.2% 빈도로 보고됐어요. 같은 항목 위약군 수치는 1.3%, 0.7%, 0.7%였죠. 약을 먹은 945명 중 36명, 3.8%가 성기능 관련 이상반응을 한 번이라도 겪었다고 허가사항이 밝혀요.\n\n수치만 보면 부담스럽죠. 그런데 허가사항은 가역성도 같이 적어요. 이상반응 탓에 약을 끊은 사람은 중단 뒤 증상이 모두 사라졌고, 계속 먹은 사람도 대부분 시간이 지나며 회복됐다는 거죠. 끊으면 돌아온다는 점은 알아둘 만해요.\n\n빈도와 별개로 챙길 건 정신과 쪽이에요. 시판 후 보고에 우울한 기분, 우울증, 드물게 자살생각을 포함한 기분변형이 올라왔어요. 이런 신호가 보이면 혼자 버티지 말고 약을 멈춘 뒤 의료전문가와 상의하라고 허가사항이 명시해요. 같은 1mg 정제면 이 안전성 정보도 공유하니, 더 싼 제품으로 바꿔도 똑같이 체크해야 해요."
