        "content": "간기능에 이상이 있다면 엔피나정은 복용 금지가 아니라 신중 투여 대상이에요. 식약처 허가사항(품목번호 201900082, 엔피나정(피나스테리드), 대한뉴팜(주))은 이 약이 간에서 광범위하게 대사되므로 간기능에 이상이 있는 환자에 대해서는 주의하여 투여한다고 적고 있어요.\n\n동반질환이 하나 더 있어요. 허가사항은 고지단백혈증, 당뇨병성 고지질혈증, 췌장염 같은 지방대사 이상 환자나 지질성 유제를 신중히 투여해야 하는 환자도 신중 투여 대상으로 분류해요. 엔피나정의 부형제에 지질이 섞여 있어서, 지방 과부하로 특별한 위험이 예상되는 분에게 투여할 때는 혈장 지질치를 점검하라고 권장해요.\n\n정리하면 부작용 빈도 자체가 지병 때문에 몇 % 더 오른다고 허가사항에 수치로 박혀 있는 건 아니에요. 핵심은 약이 대사되는 통로(간)나 지질 대사에 이미 부담이 있는 상태라, 같은 부작용도 관리 난이도가 달라진다는 점이에요. 그래서 간 수치나 지질 수치에 문제가 있는 분은 복용 전 의사와 상의하는 게 먼저예요.",
