        "content": "정신과적 증상이 가장 먼저 챙겨야 할 즉시 상담 신호예요. 식약처 허가사항은 피나스테리드 1mg을 투여한 환자에서 우울한 기분, 우울증이 보고됐고 이보다 적은 건수로 자살 생각을 포함한 기분 변형이 보고됐다고 적어요. 이런 증상이 발생하면 투여를 중단하고 의료전문가에게 상담하도록 안내하고 있어요.\n\n두 번째는 유방 변화예요. 허가사항은 멍울, 통증, 유두 분비물, 유방 비대, 압통, 신생물 같은 유방의 변화가 있으면 신속히 의사에게 보고하라고 명시해요. 시판 후 보고에는 남성 유방암 사례도 포함돼 있어서, 유방 쪽 변화는 가볍게 넘기지 말아야 해요.\n\n세 번째는 과민반응이에요. 발진, 가려움, 두드러기에 더해 입술·혀·목구멍·얼굴이 붓는 혈관부종이 나타나면 응급 상황에 가까워요. 간기능 동반질환이 있는 분이라면 허가사항에 시판 후 보고로 적힌 간효소 수치 상승도 함께 신경 쓰는 게 좋아요. 이런 신호는 빈도가 낮아도 즉시 의사·약사와 상의해야 하는 항목이에요."
