        "content": "헤어페시아정 복용법은 단계가 단순해요. 식약처 허가사항(품목번호 200605386) 기준으로 1일 1회, 1정에 든 피나스테리드 1mg을 그대로 삼키면 끝이에요. 동화약품(주)이 만든 필름코팅정이라 물 한 모금과 함께 통째로 넘기면 돼요.\n\n1단계는 정제를 쪼개거나 부수지 않는 거예요. 코팅이 주성분과의 접촉을 막아줘요. 부서진 조각을 임산부가 만지면 남성 태아에 위험이 될 수 있어서 식약처 허가사항이 따로 경고하고 있어요. 2단계는 물과 함께 삼키기, 3단계는 그 시간을 매일 지키기예요.\n\n용량을 임의로 늘리지 않는 것도 중요해요. 허가사항에는 용량을 증량해도 유효성이 증대된다는 근거가 없다고 적혀 있어요. 1일 1mg, 이 한 알이 정량이에요. 더 먹는다고 머리가 더 나지는 않아요. 부작용 위험만 올라가요."
