        "content": "횟수와 양부터 답하면 1일 1회 1정, 곧 피나스테리드 1mg이에요. 식약처 허가사항(품목번호 200605386)은 식사와 관계없이 투여할 수 있다고 명시해요. 아침 식사 전이든 저녁 식후든, 자기 전이든 시점은 자유예요.\n\n타이밍에서 진짜 중요한 건 시각 자체가 아니에요. 일관성이에요. 출근 전 양치 직후나 잠들기 전처럼, 매일 빠뜨리지 않을 한 시점을 정해 루틴으로 묶는 게 좋아요. 식전·식후를 따질 필요가 없으니 가장 안 까먹는 순간이 곧 정답이에요.\n\n허가 대상은 성인 남성(만 18∼41세)의 남성형 탈모증이에요. 만 18세 미만 소아나 여성에게는 투여하면 안 돼요. 효과는 3개월 이상 이어 먹어야 나타나요. 그 뒤로도 치료효과 유지를 위해 계속 복용하도록 허가사항이 권장해요."
