        "content": "가장 분명한 금기는 여성과 소아예요. 식약처 허가사항(품목번호 200605386)은 이 약을 임부·임신 가능성이 있는 여성과 소아에게 투여해서는 안 된다고 못 박고 있어요. 피나스테리드 같은 5α-환원효소 억제제는 남성 태아 외부생식기 발달에 이상을 일으킬 수 있어요.\n\n성분에 과민반응이 있는 사람도 피해야 해요. 전립샘비대증으로 같은 성분 5mg이나 다른 5α-환원효소 억제제를 이미 쓰는 경우 중복 복용은 금물이에요. 유당이 들어 있어 갈락토오스 불내성 같은 유전적 문제가 있으면 투여하면 안 돼요. 간 기능이 떨어진 분은 신중히 복용하도록 허가사항이 안내해요.\n\n헤어페시아정은 전문의약품이라 의사 처방이 전제예요. 약 선택이나 변경은 자가 판단 대신 의사와 상의하는 게 원칙이에요. 보고된 약물상호작용은 분명히 밝혀진 게 없어요. 그래도 복용 중인 약이 있다면 신고번호가 있는 정식 의약품인지와 함께 미리 알리는 편이 안전해요."
