        "content": "효과가 보이는 시점을 묻는다면, 답은 하루 용량을 빠짐없이 채운 채로 몇 달이 지난 뒤예요. 식약처 허가사항은 정해진 용법·용량으로 3~4개월을 복용해도 증상이 나아지지 않으면 그때 복용을 멈추고 의사 또는 약사와 상의하라고 적어요. 이 3~4개월이 곧 효과를 따져 묻는 1차 마감선인 셈이죠. 이렇게 길게 잡는 데는 까닭이 있어요. 머리카락 한 올이 영양을 받아 눈에 띌 만큼 길어지기까지는 제 나름의 속도가 있어서, 성인이 하루 3캡슐씩 부지런히 채워도 거울 앞에서 표가 나려면 시간이 쌓여야 해요. 그래서 시작하고 1~2주 만에 변화가 없다고 약을 내려놓으면 마감선의 발끝에도 못 간 거예요. 신호는 조용히 와요. 빠지는 양이 한 줌씩 줄거나 손상모의 거칠던 결이 누그러지는 식이죠. 반대로 머리가 아닌 곳에 털이 돋는 변화가 보이면, 그건 멈춰야 한다는 신호라 허가사항도 복용 중단과 상담을 안내해요. 좋아지는 쪽과 멈춰야 하는 쪽을 함께 지켜보며 3~4개월 단위로 끊어 점검하는 흐름을 권해요.",
